  1→//! Variable interpolation for configuration values.
  2→//!
  3→//! Bivvy supports variable interpolation in config values using `${variable}` syntax.
  4→//!
  5→//! # Syntax
  6→//!
  7→//! - `${variable_name}` - replaced with variable value
  8→//! - `$${escaped}` - produces literal `${escaped}` in output
  9→//!
 10→//! # Example
 11→//!
 12→//! ```yaml
 13→//! command: "echo Hello, ${name}!"
 14→//! # With name="World", produces: echo Hello, World!
 15→//! ```
 16→
 17→use crate::error::{BivvyError, Result};
 18→use std::collections::{HashMap, HashSet};
 19→
 20→/// A segment of an interpolated string.
 21→#[derive(Debug, Clone, PartialEq)]
 22→pub enum Segment {
 23→    /// Literal text
 24→    Literal(String),
 25→    /// Variable reference: ${name}
 26→    Variable(String),
 27→}
 28→
 29→/// Parse a string containing ${var} interpolations.
 30→///
 31→/// Supports:
 32→/// - `${variable_name}` - variable interpolation
 33→/// - `$${escaped}` - literal `${escaped}` in output
 34→///
 35→/// # Returns
 36→///
 37→/// Vec of segments representing the parsed string
 38→pub fn parse_interpolation(input: &str) -> Vec<Segment> {
 39→    let mut segments = Vec::new();
 40→    let mut chars = input.chars().peekable();
 41→    let mut current_literal = String::new();
 42→
 43→    while let Some(c) = chars.next() {
 44→        if c == '$' {
 45→            match chars.peek() {
 46→                Some('$') => {
 47→                    // Escaped: $$ becomes $
 48→                    chars.next();
 49→                    if chars.peek() == Some(&'{') {
 50→                        // $${...} -> literal ${...}
 51→                        chars.next(); // consume {
 52→                        current_literal.push('$');
 53→                        current_literal.push('{');
 54→                        // Read until closing brace
 55→                        while let Some(&c) = chars.peek() {
 56→                            chars.next();
 57→                            current_literal.push(c);
 58→                            if c == '}' {
 59→                                break;
 60→                            }
 61→                        }
 62→                    } else {
 63→                        current_literal.push('$');
 64→                    }
 65→                }
 66→                Some('{') => {
 67→                    // Start of variable
 68→                    chars.next(); // consume {
 69→
 70→                    // Flush current literal
 71→                    if !current_literal.is_empty() {
 72→                        segments.push(Segment::Literal(std::mem::take(&mut current_literal)));
 73→                    }
 74→
 75→                    // Read variable name until }
 76→                    let mut var_name = String::new();
 77→                    while let Some(&c) = chars.peek() {
 78→                        if c == '}' {
 79→                            chars.next();
 80→                            break;
 81→                        }
 82→                        var_name.push(chars.next().unwrap());
 83→                    }
 84→
 85→                    segments.push(Segment::Variable(var_name));
 86→                }
 87→                _ => {
 88→                    current_literal.push(c);
 89→                }
 90→            }
 91→        } else {
 92→            current_literal.push(c);
 93→        }
 94→    }
 95→
 96→    // Flush remaining literal
 97→    if !current_literal.is_empty() {
 98→        segments.push(Segment::Literal(current_literal));
 99→    }
100→

 1→//! Built-in templates embedded at compile time.
 2→
 3→use crate::error::Result;
 4→use crate::registry::manifest::RegistryManifest;
 5→use crate::registry::template::{Template, TemplateSource};
 6→use include_dir::{include_dir, Dir};
 7→use std::collections::HashMap;
 8→
 9→/// Embedded templates directory.
10→static TEMPLATES_DIR: Dir<'_> = include_dir!("$CARGO_MANIFEST_DIR/templates");
11→
12→/// Load the built-in registry manifest.
13→pub fn load_manifest() -> Result<RegistryManifest> {
14→    let manifest_file = TEMPLATES_DIR.get_file("registry.yml").ok_or_else(|| {
15→        crate::error::BivvyError::ConfigNotFound {
16→            path: "templates/registry.yml".into(),
17→        }
18→    })?;
19→
20→    let content = manifest_file.contents_utf8().ok_or_else(|| {
21→        crate::error::BivvyError::ConfigParseError {
22→            path: "templates/registry.yml".into(),
23→            message: "Invalid UTF-8".to_string(),
24→        }
25→    })?;
26→
27→    serde_yaml::from_str(content).map_err(|e| crate::error::BivvyError::ConfigParseError {
28→        path: "templates/registry.yml".into(),
29→        message: e.to_string(),
30→    })
31→}
32→
33→/// Load all built-in templates.
34→pub fn load_templates() -> Result<HashMap<String, Template>> {
35→    let mut templates = HashMap::new();
36→    load_templates_from_dir(&TEMPLATES_DIR, "steps", &mut templates)?;
37→    Ok(templates)
38→}
39→
40→fn load_templates_from_dir(
41→    dir: &Dir<'_>,
42→    prefix: &str,
43→    templates: &mut HashMap<String, Template>,
44→) -> Result<()> {
45→    let steps_dir = dir.get_dir(prefix);
46→
47→    if let Some(steps) = steps_dir {
48→        for entry in steps.dirs() {
49→            // Each subdirectory is a category (ruby, node, common, etc.)
50→            for file in entry.files() {
51→                if let Some(ext) = file.path().extension() {
52→                    if ext == "yml" || ext == "yaml" {
53→                        if let Some(content) = file.contents_utf8() {
54→                            let template: Template =
55→                                serde_yaml::from_str(content).map_err(|e| {
56→                                    crate::error::BivvyError::ConfigParseError {
57→                                        path: file.path().to_path_buf(),
58→                                        message: e.to_string(),
59→                                    }
60→                                })?;
61→                            templates.insert(template.name.clone(), template);
62→                        }
63→                    }
64→                }
65→            }
66→        }
67→    }
68→
69→    Ok(())
70→}
71→
72→/// Check if a template exists in built-ins.
73→pub fn has_template(name: &str) -> bool {
74→    load_templates()
75→        .map(|t| t.contains_key(name))
76→        .unwrap_or(false)
77→}
