        let config = BivvyConfig {
            extends: Some(vec![ExtendsConfig {
                url: server.url("/base.yml"),
            }]),
            ..Default::default()
        };

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&config).unwrap();

        assert!(
            resolved.extends.is_none(),
            "extends should be cleared after resolution"
        );
    }

    #[test]
    fn multiple_extends_merge_in_order() {
        let server = MockServer::start();

        let first_yaml = r#"
app_name: First
steps:
  step_a:
    command: from-first
  step_shared:
    command: from-first
"#;

        let second_yaml = r#"
app_name: Second
steps:
  step_b:
    command: from-second
  step_shared:
    command: from-second
"#;

        server.mock(|when, then| {
            when.method(GET).path("/first.yml");
            then.status(200).body(first_yaml);
        });

        server.mock(|when, then| {
            when.method(GET).path("/second.yml");
            then.status(200).body(second_yaml);
        });

        let config = BivvyConfig {
            extends: Some(vec![
                ExtendsConfig {
                    url: server.url("/first.yml"),
                },
                ExtendsConfig {
                    url: server.url("/second.yml"),
                },
            ]),
            ..Default::default()
        };

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&config).unwrap();

        // Both unique steps present
        assert!(resolved.steps.contains_key("step_a"));
        assert!(resolved.steps.contains_key("step_b"));

        // Later base overrides earlier for shared step
        assert_eq!(
            resolved.steps["step_shared"].command,
            Some("from-second".to_string())
        );
    }

    #[test]
    fn extends_env_override_replaces_ci_block() {
        let server = MockServer::start();

        let base_yaml = r#"
app_name: BaseApp
steps:
  db:
    command: "db-setup"
    environments:
      ci:
        command: "pg_isready"
        env:
          A: "1"
"#;

        server.mock(|when, then| {
            when.method(GET).path("/base.yml");
            then.status(200).body(base_yaml);
        });

        // Overlay replaces ci block entirely
        let mut steps = std::collections::HashMap::new();
        let mut envs = std::collections::HashMap::new();
        let mut env_vars = std::collections::HashMap::new();
        env_vars.insert("FOO".to_string(), Some("1".to_string()));
        envs.insert(
            "ci".to_string(),
            super::super::schema::StepEnvironmentOverride {
                env: env_vars,
                ..Default::default()
            },
        );
        steps.insert(
            "db".to_string(),
            super::super::schema::StepConfig {
                environments: envs,
                ..Default::default()
            },
        );

        let config = BivvyConfig {
            extends: Some(vec![ExtendsConfig {
                url: server.url("/base.yml"),
            }]),
            steps,
            ..Default::default()
        };

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&config).unwrap();

        let ci = &resolved.steps["db"].environments["ci"];
        // Overlay's env is present
        assert_eq!(ci.env.get("FOO"), Some(&Some("1".to_string())));
        // Base's command is gone (block replaced, not merged)
        assert!(ci.command.is_none());
        // Base's env.A is gone
        assert!(!ci.env.contains_key("A"));
    }

    #[test]
    fn extends_env_override_adds_new_environment() {
        let server = MockServer::start();

        let base_yaml = r#"
app_name: BaseApp
steps:
  db:
    command: "db-setup"
    environments:
      ci:
        command: "ci-cmd"
"#;

        server.mock(|when, then| {
            when.method(GET).path("/base.yml");
            then.status(200).body(base_yaml);
        });

        // Overlay adds staging without affecting ci
        let mut steps = std::collections::HashMap::new();
        let mut envs = std::collections::HashMap::new();
        envs.insert(
            "staging".to_string(),
            super::super::schema::StepEnvironmentOverride {
                command: Some("staging-cmd".to_string()),
                ..Default::default()
            },
        );
        steps.insert(
            "db".to_string(),
            super::super::schema::StepConfig {
                environments: envs,
                ..Default::default()
            },
        );

        let config = BivvyConfig {
            extends: Some(vec![ExtendsConfig {
                url: server.url("/base.yml"),
            }]),
            steps,
            ..Default::default()
        };

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&config).unwrap();

        // ci preserved from base
        assert_eq!(
            resolved.steps["db"].environments["ci"].command,
            Some("ci-cmd".to_string())
        );
        // staging added from overlay
        assert_eq!(
            resolved.steps["db"].environments["staging"].command,
            Some("staging-cmd".to_string())
        );
    }

    #[test]
    fn extends_env_override_preserves_unmentioned_environments() {
        let server = MockServer::start();

        let base_yaml = r#"
app_name: BaseApp
steps:
  db:
    command: "db-setup"
    environments:
      ci:
        command: "ci-cmd"
      staging:
        command: "staging-cmd"
"#;

        server.mock(|when, then| {
            when.method(GET).path("/base.yml");
            then.status(200).body(base_yaml);
        });

        // Overlay only mentions ci
        let mut steps = std::collections::HashMap::new();
        let mut envs = std::collections::HashMap::new();
        envs.insert(
            "ci".to_string(),
            super::super::schema::StepEnvironmentOverride {
                command: Some("new-ci-cmd".to_string()),
                ..Default::default()
            },
        );
        steps.insert(
            "db".to_string(),
            super::super::schema::StepConfig {
                environments: envs,
                ..Default::default()
            },
        );

        let config = BivvyConfig {
            extends: Some(vec![ExtendsConfig {
                url: server.url("/base.yml"),
            }]),
            steps,
            ..Default::default()
        };

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&config).unwrap();

        // ci replaced
        assert_eq!(
            resolved.steps["db"].environments["ci"].command,
            Some("new-ci-cmd".to_string())
        );
        // staging preserved
        assert_eq!(
            resolved.steps["db"].environments["staging"].command,
            Some("staging-cmd".to_string())
        );
    }

    #[test]
    fn extends_only_environments_replaces_list() {
        let server = MockServer::start();

        let base_yaml = r#"
app_name: BaseApp
steps:
  db:
    command: "db-setup"
    only_environments:
      - dev
"#;

        server.mock(|when, then| {
            when.method(GET).path("/base.yml");
            then.status(200).body(base_yaml);
        });

        // Overlay replaces only_environments list
        let mut steps = std::collections::HashMap::new();
        steps.insert(
            "db".to_string(),
            super::super::schema::StepConfig {
                only_environments: vec!["dev".to_string(), "ci".to_string()],
                ..Default::default()
            },
        );

        let config = BivvyConfig {
            extends: Some(vec![ExtendsConfig {
                url: server.url("/base.yml"),
            }]),
            steps,
            ..Default::default()
        };

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&config).unwrap();

        // Array replaced entirely
        assert_eq!(
            resolved.steps["db"].only_environments,
            vec!["dev".to_string(), "ci".to_string()]
        );
    }

    #[test]
    fn extends_child_yaml_replaces_parent_ci_environment_block() {
        let server = MockServer::start();

        // Parent config: step "setup" with ci environment override
        let parent_yaml = r#"
app_name: ParentApp
steps:
  setup:
    command: "parent-default-cmd"
    environments:
      ci:
        command: "parent-ci-cmd"
        env:
          PARENT_VAR: "from-parent"
"#;

        server.mock(|when, then| {
            when.method(GET).path("/parent.yml");
            then.status(200).body(parent_yaml);
        });

        // Child config as YAML that extends parent and overrides the ci block
        let child_yaml = format!(
            r#"
extends:
  - url: {}
app_name: ChildApp
steps:
  setup:
    environments:
      ci:
        command: "child-ci-cmd"
"#,
            server.url("/parent.yml")
        );

        let child_config: BivvyConfig = serde_yaml::from_str(&child_yaml).unwrap();

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&child_config).unwrap();

        // Child's app_name wins
        assert_eq!(resolved.app_name, Some("ChildApp".to_string()));

        // The ci environment block should be fully replaced by child
        let ci = &resolved.steps["setup"].environments["ci"];
        assert_eq!(
            ci.command,
            Some("child-ci-cmd".to_string()),
            "Child's ci command should replace parent's"
        );
        // Parent's env vars should be gone (block replaced, not deep-merged)
        assert!(
            !ci.env.contains_key("PARENT_VAR"),
            "Parent's ci env vars should not survive replacement"
        );

        // Parent's default command should still be inherited (not inside environments block)
        assert_eq!(
            resolved.steps["setup"].command,
            Some("parent-default-cmd".to_string()),
            "Parent's default command should be inherited"
        );
    }

    #[test]
    fn extends_inherits_only_environments_when_unset() {
        let server = MockServer::start();

        let base_yaml = r#"
app_name: BaseApp
steps:
  db:
    command: "db-setup"
    only_environments:
      - dev
"#;

        server.mock(|when, then| {
            when.method(GET).path("/base.yml");
            then.status(200).body(base_yaml);
        });

        // Overlay doesn't mention only_environments
        let mut steps = std::collections::HashMap::new();
        steps.insert(
            "db".to_string(),
            super::super::schema::StepConfig {
                command: Some("custom-cmd".to_string()),
                ..Default::default()
            },
        );

        let config = BivvyConfig {
            extends: Some(vec![ExtendsConfig {
                url: server.url("/base.yml"),
            }]),
            steps,
            ..Default::default()
        };

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&config).unwrap();

        // Command overridden
        assert_eq!(resolved.steps["db"].command, Some("custom-cmd".to_string()));
        // only_environments inherited from base
        assert_eq!(
            resolved.steps["db"].only_environments,
            vec!["dev".to_string()]
        );
    }
}

