        let filename = path.file_name().unwrap().to_string_lossy();

        // Should be 16 hex characters (8 bytes encoded)
        assert_eq!(filename.len(), 16);
        assert!(filename.chars().all(|c| c.is_ascii_hexdigit()));
    }

