            .store("http:test", "template", "content", 3600)
            .unwrap();

        let validator = CacheValidator::new(&store);
        let result = validator
            .validate("http:test", "template", RemoteCacheStrategy::Ttl)
            .unwrap();

        assert_eq!(result, ValidationResult::Fresh);
    }

    #[test]
